import{_ as t,o as a,c as o,ae as s}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Release Evidence Plan","description":"","frontmatter":{},"headers":[],"relativePath":"plans/tasks/release-evidence.md","filePath":"plans/tasks/release-evidence.md"}'),i={name:"plans/tasks/release-evidence.md"};function d(r,e,c,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="release-evidence-plan" tabindex="-1">Release Evidence Plan <a class="header-anchor" href="#release-evidence-plan" aria-label="Permalink to &quot;Release Evidence Plan&quot;">​</a></h1><p><strong>Status:</strong> Merged to <code>main</code> as commit <code>27876400</code> (PR <a href="https://github.com/KooshaPari/HeliosLab/pull/202" target="_blank" rel="noreferrer">#202</a>) — Slice 3 of 5. <strong>See also:</strong> <a href="./../WBS.html"><code>docs/plans/WBS.md</code></a>. <strong>Branch:</strong> <code>wbs/release-evidence</code> (deleted post-merge). <strong>Date:</strong> 2026-09-20 <strong>Goal:</strong> Make every <code>release:</code> commit on <code>main</code> carry a complete evidence bundle that downstream consumers can verify, without requiring an out-of-band doc.</p><hr><h2 id="why-this-slice-exists" tabindex="-1">Why this slice exists <a class="header-anchor" href="#why-this-slice-exists" aria-label="Permalink to &quot;Why this slice exists&quot;">​</a></h2><p>Before this slice, three release-evidence artefacts lived in this repo:</p><ul><li><code>.github/workflows/release.yml</code> — publishes Rust crates to crates.io on a <code>release:</code> commit to <code>main</code>, with <strong>no SLSA, no SBOM, no manifest</strong>.</li><li><code>.github/workflows/release-attestation.yml</code> — generates SLSA Build L2 provenance, but only fires on <code>release: published</code> (a GitHub Release event that <code>release.yml</code> never creates) or on manual dispatch.</li><li><code>docs/slsa.md</code> — claimed &quot;SLSA Build L2 (achieved today)&quot; based on the attestation workflow existing, not on it actually firing.</li></ul><p>The two workflows were decoupled: the path that actually publishes artifacts (<code>release.yml</code>) produced zero evidence, while the path that generated evidence (<code>release-attestation.yml</code>) was effectively dead. A <code>chore(release): v0.14.11-canary.3</code> commit could land, ship to crates.io, and leave no trace of what was built or where.</p><p>The previous version of this file (<code>release-evidence-v0.14.11-canary.3.md</code>, on <code>wbs/terminal-slice</code>) was hand-written and inaccurate — it claimed the <code>VERSION</code> file had been updated to <code>canary.3</code> when in fact it was still at <code>canary.1</code>. That is the exact failure mode this slice exists to prevent: release evidence that drifts from reality because it is produced by humans rather than enforced by CI.</p><h2 id="what-this-slice-delivers" tabindex="-1">What this slice delivers <a class="header-anchor" href="#what-this-slice-delivers" aria-label="Permalink to &quot;What this slice delivers&quot;">​</a></h2><h3 id="_1-evidence-gate-workflow" tabindex="-1">1. Evidence gate workflow <a class="header-anchor" href="#_1-evidence-gate-workflow" aria-label="Permalink to &quot;1. Evidence gate workflow&quot;">​</a></h3><p><code>.github/workflows/release-evidence.yml</code> runs as a <code>workflow_run</code> follower on <code>Release</code> and <code>Release Attestation</code> completions on <code>main</code>, plus manual <code>workflow_dispatch</code>. The gate is <strong>post-merge</strong> by design: release evidence (SBOM, BUILD_MANIFEST, SLSA provenance) is produced by <code>release.yml</code> and <code>release-attestation.yml</code>, which themselves only fire on push to <code>main</code>. Pre-merge validation cannot reach those artifacts. The gate posts a single check named <strong>Release Evidence</strong> that branch protection may require. The job:</p><ol><li>Resolves the commit SHA from the triggering <code>workflow_run.event</code> (or the manual <code>inputs.commit</code>).</li><li>Calls <code>actions:listWorkflowRunsForRepo</code>, filters to runs on the same <code>head_sha</code> with <code>conclusion === &#39;success&#39;</code>, and identifies the matching <code>Release</code> and <code>Release Attestation</code> runs.</li><li>Downloads every artifact from each matched run into <code>/tmp/release-evidence-artifacts/&lt;artifact-name&gt;/</code>, then extracts every <code>.zip</code> so the validator scans a flat tree of real files.</li><li>Runs the validator (<code>bun run scripts/release-evidence-validate.ts --download-dir /tmp/release-evidence-artifacts --commit &lt;sha&gt;</code>).</li><li>Uploads <code>.gate-reports/release-evidence.json</code> as a workflow artefact for human inspection.</li></ol><p>Triggering on <code>workflow_run</code> (rather than <code>push</code>) eliminates the race-condition class of bugs that v1 had: by the time this gate starts, both upstream runs have a known terminal <code>conclusion</code>, so the gate does not have to retry or poll. The checkout action uses the same resolved SHA via <code>ref:</code> so all version checks see the validated commit, not the workflow run&#39;s HEAD.</p><p>The CLI surface of the validator (<code>--download-dir</code>) accepts the path to a directory of downloaded artifacts. The directory layout may have each artifact in its own subdirectory (<code>&lt;download-dir&gt;/&lt;artifact-name&gt;/&lt;file&gt;</code>), which matches the layout produced by <code>actions/download-artifact@v4</code> once each archive is unzipped. The validator walks the tree recursively and matches files by basename (and for SBOM/manifest by exact relative path), so either layout works.</p><p>GitHub Actions does not register brand-new workflows that exist only on a PR branch; the workflow file must land on <code>main</code> before it fires automatically. This is documented GitHub behavior; the workaround is to merge the slice first, after which every subsequent release commit runs the gate.</p><h3 id="_2-validator-script-and-tests" tabindex="-1">2. Validator script and tests <a class="header-anchor" href="#_2-validator-script-and-tests" aria-label="Permalink to &quot;2. Validator script and tests&quot;">​</a></h3><p><code>scripts/release-evidence-validate.ts</code> is the unit-testable core. It exports eight pure functions (<code>readVersionFile</code>, <code>readPackageJsonVersion</code>, <code>readCargoWorkspaceVersion</code>, <code>listFilesRecursive</code>, <code>anyFileMatchesBasenames</code>, <code>checkVersionConsistency</code>, <code>checkArtifactPresence</code>) and a CLI entry point guarded by <code>import.meta.main</code>.</p><p>The validator checks, in order:</p><table tabindex="0"><thead><tr><th>Check</th><th>Source</th><th>Required</th></tr></thead><tbody><tr><td><code>version-consistency</code></td><td><code>VERSION</code>, <code>package.json</code>, <code>Cargo.toml</code></td><td>yes</td></tr><tr><td><code>sbom-present</code></td><td>files inside the downloaded artifacts dir</td><td>yes</td></tr><tr><td><code>build-manifest-present</code></td><td>files inside the downloaded artifacts dir</td><td>yes</td></tr><tr><td><code>slsa-provenance-attached</code></td><td>files ending in <code>.intoto.jsonl</code> in the dir</td><td>yes</td></tr></tbody></table><p>A <code>skip</code> status is allowed when the workflow did not download any artifacts (the upstream <code>Release</code> or <code>Release Attestation</code> workflows did not run for this SHA). All checks must pass or skip for <code>ok: true</code>.</p><p>27 unit tests in <code>scripts/tests/release-evidence-validate.test.ts</code> exercise every path through the validator with on-disk fixtures, no network or git history required. The fixture suite covers:</p><ul><li>empty / malformed version files</li><li>all-three-agree, two-agree-one-disagree, one-missing, all-missing</li><li><code>listFilesRecursive</code> walks nested dirs and produces forward-slash relative paths on POSIX and Windows</li><li><code>anyFileMatchesBasenames</code> matches by basename or by exact path</li><li>SBOM / BUILD_MANIFEST detection in subdirectories</li><li>provenance detection via <code>.intoto.jsonl</code></li><li><code>skip</code> when no download directory is provided</li></ul><h3 id="_3-required-check-manifest-update" tabindex="-1">3. Required-check manifest update <a class="header-anchor" href="#_3-required-check-manifest-update" aria-label="Permalink to &quot;3. Required-check manifest update&quot;">​</a></h3><p><code>.github/required-checks.txt</code> adds a new line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>release-evidence.yml|Release Evidence</span></span></code></pre></div><p>so the existing <code>required-check-names-guard.yml</code> workflow enforces that the gate&#39;s job name exists. This does not change branch protection on <code>main</code>; the guard is a self-consistency check on the manifest, not a required status check.</p><h3 id="_4-documentation" tabindex="-1">4. Documentation <a class="header-anchor" href="#_4-documentation" aria-label="Permalink to &quot;4. Documentation&quot;">​</a></h3><ul><li><code>docs/slsa.md</code> — replaced &quot;achieved today&quot; with the truthful &quot;partial coverage as of v0.14.11-canary.3&quot;. Added an explicit &quot;What is enforced today&quot; section that points at the gate, and a &quot;What is not yet enforced&quot; section that names the SBOM-generation and cosign-signing gaps as future work.</li><li><code>docs/plans/tasks/release-evidence.md</code> (this file) — the plan, in the same per-release format as <code>release-evidence-v0.14.11-canary.3.md</code>.</li><li><code>VERSION</code> — fixed from <code>0.14.11-canary.1</code> to <code>0.14.11-canary.3</code> so all three version sources agree. Without this fix the gate correctly fails the validator on every release commit; the fix demonstrates the gate&#39;s effectiveness.</li></ul><h2 id="test-results" tabindex="-1">Test results <a class="header-anchor" href="#test-results" aria-label="Permalink to &quot;Test results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Tests</th><th>Pass</th><th>Fail</th></tr></thead><tbody><tr><td><code>scripts/tests/release-evidence-validate.test.ts</code></td><td>27</td><td>27</td><td>0</td></tr></tbody></table><h2 id="quality-gates" tabindex="-1">Quality gates <a class="header-anchor" href="#quality-gates" aria-label="Permalink to &quot;Quality gates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gate</th><th>Status</th></tr></thead><tbody><tr><td><code>bun test scripts/tests/release-evidence-validate.test.ts</code></td><td>27/27 pass</td></tr><tr><td>Validator catches real bugs</td><td>yes (VERSION mismatch detected)</td></tr><tr><td>Validator returns non-zero on failure</td><td>yes (<code>process.exit(1)</code>)</td></tr><tr><td>Static-analysis gate</td><td>PASS</td></tr></tbody></table><h2 id="version-consistency" tabindex="-1">Version consistency <a class="header-anchor" href="#version-consistency" aria-label="Permalink to &quot;Version consistency&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Version</th></tr></thead><tbody><tr><td><code>package.json</code></td><td>0.14.11-canary.3</td></tr><tr><td><code>Cargo.toml</code></td><td>0.14.11-canary.3</td></tr><tr><td><code>VERSION</code></td><td>0.14.11-canary.3 (was 0.14.11-canary.1, fixed in this slice)</td></tr></tbody></table><h2 id="open-follow-ups-not-in-this-slice" tabindex="-1">Open follow-ups (not in this slice) <a class="header-anchor" href="#open-follow-ups-not-in-this-slice" aria-label="Permalink to &quot;Open follow-ups (not in this slice)&quot;">​</a></h2><ol><li><strong>SBOM generation inside <code>release.yml</code></strong> — the gate currently verifies that an SBOM <em>exists</em>, but <code>release.yml</code> does not yet run <code>cargo-cyclonedx sbom</code> to produce one. Adding that step is a separate slice.</li><li><strong>Cosign signing of release binaries</strong> — the gate validates provenance metadata exists but does not verify that the binaries themselves are signed. Wiring <code>cosign sign-blob</code> with keyless OIDC into <code>release.yml</code> is a separate slice.</li><li><strong>Per-release evidence doc auto-generation</strong> — replace the hand-written <code>release-evidence-v0.14.11-canary.3.md</code> format with a generated report produced by the gate at release time. The current slice lays the foundation; the generator is a follow-up.</li></ol><h2 id="how-to-verify-locally" tabindex="-1">How to verify locally <a class="header-anchor" href="#how-to-verify-locally" aria-label="Permalink to &quot;How to verify locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Validator runs the version-consistency check (passes) and skips</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># artifact checks because no downloaded dir is provided in the local</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># dev environment. The CI workflow passes --download-dir.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/release-evidence-validate.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the unit tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests/release-evidence-validate.test.ts</span></span></code></pre></div><p>When the first real <code>release:</code> commit is pushed, the gate runs end-to-end: <code>release.yml</code> ships artifacts, <code>release-attestation.yml</code> produces SLSA provenance, <code>release-evidence.yml</code> follows both via <code>workflow_run</code>, downloads all artifacts, the validator returns 0, the check turns green.</p>`,39)])])}const m=t(i,[["render",d]]);export{p as __pageData,m as default};
